DROP DATABASE IF EXISTS startup_portal;
CREATE DATABASE startup_portal CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE startup_portal;

CREATE TABLE roles (id INT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(30) UNIQUE NOT NULL);
CREATE TABLE users (
 id INT PRIMARY KEY AUTO_INCREMENT, role_id INT NOT NULL, name VARCHAR(120) NOT NULL,
 email VARCHAR(160) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, avatar VARCHAR(255),
 verified TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(role_id) REFERENCES roles(id)
);
CREATE TABLE student_profiles (user_id INT PRIMARY KEY, bio TEXT, education VARCHAR(255), interests VARCHAR(500), github_url VARCHAR(255), portfolio_url VARCHAR(255), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE mentor_profiles (user_id INT PRIMARY KEY, expertise VARCHAR(500), industry VARCHAR(150), years_experience INT DEFAULT 0, availability VARCHAR(80), preferred_stages VARCHAR(250), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE investor_profiles (user_id INT PRIMARY KEY, sectors VARCHAR(500), stages VARCHAR(250), min_ticket DECIMAL(14,2), max_ticket DECIMAL(14,2), geography VARCHAR(150), thesis TEXT, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE incubators (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, name VARCHAR(180) NOT NULL, description TEXT, location VARCHAR(150), verified TINYINT(1) DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE startups (id INT PRIMARY KEY AUTO_INCREMENT, owner_id INT NOT NULL, name VARCHAR(180) NOT NULL, industry VARCHAR(120), location VARCHAR(120), problem TEXT, solution TEXT, business_model VARCHAR(255), target_market VARCHAR(255), stage ENUM('Idea','Validation','Prototype','MVP','Traction','Fundraising','Growth') DEFAULT 'Idea', traction VARCHAR(255), revenue DECIMAL(14,2) DEFAULT 0, funding_requirement DECIMAL(14,2) DEFAULT 0, website VARCHAR(255), pitch_info TEXT, status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE startup_members (startup_id INT, user_id INT, member_role VARCHAR(80), PRIMARY KEY(startup_id,user_id), FOREIGN KEY(startup_id) REFERENCES startups(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE ideas (id INT PRIMARY KEY AUTO_INCREMENT, creator_id INT NOT NULL, title VARCHAR(180) NOT NULL, problem TEXT, solution TEXT, target_users VARCHAR(255), industry VARCHAR(120), technologies VARCHAR(255), stage VARCHAR(80), required_skills VARCHAR(500), status VARCHAR(50) DEFAULT 'Idea', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(creator_id) REFERENCES users(id));
CREATE TABLE projects (id INT PRIMARY KEY AUTO_INCREMENT, owner_id INT NOT NULL, idea_id INT NULL, name VARCHAR(180) NOT NULL, description TEXT, domain VARCHAR(120), status VARCHAR(50) DEFAULT 'Active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(idea_id) REFERENCES ideas(id) ON DELETE SET NULL);
CREATE TABLE project_members (project_id INT, user_id INT, member_role VARCHAR(50) DEFAULT 'Contributor', joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(project_id,user_id), FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE project_issues (id INT PRIMARY KEY AUTO_INCREMENT, project_id INT NOT NULL, title VARCHAR(200) NOT NULL, description TEXT, issue_type VARCHAR(50) DEFAULT 'Task', priority VARCHAR(30) DEFAULT 'Medium', status ENUM('Backlog','In Progress','Review','Completed') DEFAULT 'Backlog', assignee_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(assignee_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE project_milestones (id INT PRIMARY KEY AUTO_INCREMENT, project_id INT NOT NULL, title VARCHAR(180) NOT NULL, due_date DATE, status VARCHAR(50) DEFAULT 'Planned', FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE collaboration_requests (id INT PRIMARY KEY AUTO_INCREMENT, project_id INT NOT NULL, requester_id INT NOT NULL, target_id INT NOT NULL, message TEXT, status ENUM('Pending','Accepted','Rejected') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(project_id) REFERENCES projects(id), FOREIGN KEY(requester_id) REFERENCES users(id), FOREIGN KEY(target_id) REFERENCES users(id));
CREATE TABLE mentorship_requests (id INT PRIMARY KEY AUTO_INCREMENT, requester_id INT NOT NULL, mentor_id INT NOT NULL, startup_id INT NULL, goal TEXT, status ENUM('Pending','Accepted','Rejected') DEFAULT 'Pending', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(requester_id) REFERENCES users(id), FOREIGN KEY(mentor_id) REFERENCES users(id), FOREIGN KEY(startup_id) REFERENCES startups(id) ON DELETE SET NULL);
CREATE TABLE mentorships (id INT PRIMARY KEY AUTO_INCREMENT, request_id INT NOT NULL, goal TEXT, progress INT DEFAULT 0, status VARCHAR(40) DEFAULT 'Active', FOREIGN KEY(request_id) REFERENCES mentorship_requests(id));
CREATE TABLE mentorship_sessions (id INT PRIMARY KEY AUTO_INCREMENT, mentorship_id INT NOT NULL, scheduled_at DATETIME, topic VARCHAR(200), notes TEXT, status VARCHAR(40) DEFAULT 'Scheduled', FOREIGN KEY(mentorship_id) REFERENCES mentorships(id) ON DELETE CASCADE);
CREATE TABLE mentor_evaluations (id INT PRIMARY KEY AUTO_INCREMENT, mentor_id INT NOT NULL, startup_id INT NOT NULL, problem_validation INT, solution_score INT, market_score INT, team_score INT, product_score INT, business_model_score INT, traction_score INT, fundraising_readiness INT, comments TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(mentor_id) REFERENCES users(id), FOREIGN KEY(startup_id) REFERENCES startups(id));
CREATE TABLE incubation_programs (id INT PRIMARY KEY AUTO_INCREMENT, incubator_id INT NOT NULL, name VARCHAR(180) NOT NULL, description TEXT, duration_months INT, eligibility TEXT, focus_areas VARCHAR(500), cohort_size INT, deadline DATE, status VARCHAR(40) DEFAULT 'Open', FOREIGN KEY(incubator_id) REFERENCES incubators(id));
CREATE TABLE cohorts (id INT PRIMARY KEY AUTO_INCREMENT, program_id INT NOT NULL, name VARCHAR(160) NOT NULL, start_date DATE, end_date DATE, FOREIGN KEY(program_id) REFERENCES incubation_programs(id));
CREATE TABLE incubation_applications (id INT PRIMARY KEY AUTO_INCREMENT, startup_id INT NOT NULL, program_id INT NOT NULL, problem TEXT, solution TEXT, market TEXT, team TEXT, business_model TEXT, traction TEXT, funding_requirement DECIMAL(14,2), pitch_deck VARCHAR(255), status ENUM('Draft','Submitted','Screening','Shortlisted','Interview','Accepted','Rejected') DEFAULT 'Draft', applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(startup_id) REFERENCES startups(id), FOREIGN KEY(program_id) REFERENCES incubation_programs(id));
CREATE TABLE startup_milestones (id INT PRIMARY KEY AUTO_INCREMENT, startup_id INT NOT NULL, title VARCHAR(180) NOT NULL, due_date DATE, status VARCHAR(40) DEFAULT 'Planned', FOREIGN KEY(startup_id) REFERENCES startups(id) ON DELETE CASCADE);
CREATE TABLE support_requests (id INT PRIMARY KEY AUTO_INCREMENT, startup_id INT NOT NULL, category VARCHAR(100), description TEXT, status VARCHAR(40) DEFAULT 'Requested', FOREIGN KEY(startup_id) REFERENCES startups(id));
CREATE TABLE investor_preferences (id INT PRIMARY KEY AUTO_INCREMENT, investor_id INT NOT NULL, sector VARCHAR(120), stage VARCHAR(80), min_ticket DECIMAL(14,2), max_ticket DECIMAL(14,2), FOREIGN KEY(investor_id) REFERENCES users(id));
CREATE TABLE deals (id INT PRIMARY KEY AUTO_INCREMENT, investor_id INT NOT NULL, startup_id INT NOT NULL, title VARCHAR(180), stage ENUM('New Opportunity','Screening','Review','Due Diligence','Term Sheet','Negotiation','Invested','Passed') DEFAULT 'New Opportunity', amount DECIMAL(14,2), interest VARCHAR(30) DEFAULT 'Interested', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(investor_id) REFERENCES users(id), FOREIGN KEY(startup_id) REFERENCES startups(id));
CREATE TABLE due_diligence_documents (id INT PRIMARY KEY AUTO_INCREMENT, deal_id INT NOT NULL, category VARCHAR(80), document_name VARCHAR(200), status ENUM('Requested','Uploaded','Under Review','Verified','Issue') DEFAULT 'Requested', file_url VARCHAR(255), FOREIGN KEY(deal_id) REFERENCES deals(id) ON DELETE CASCADE);
CREATE TABLE investments (id INT PRIMARY KEY AUTO_INCREMENT, deal_id INT NOT NULL, amount DECIMAL(14,2), equity_percent DECIMAL(6,2), investment_date DATE, notes TEXT, FOREIGN KEY(deal_id) REFERENCES deals(id));
CREATE TABLE challenges (id INT PRIMARY KEY AUTO_INCREMENT, creator_id INT NOT NULL, title VARCHAR(180) NOT NULL, problem_statement TEXT, description TEXT, domain VARCHAR(120), deadline DATE, eligibility TEXT, status VARCHAR(40) DEFAULT 'Open', FOREIGN KEY(creator_id) REFERENCES users(id));
CREATE TABLE challenge_submissions (id INT PRIMARY KEY AUTO_INCREMENT, challenge_id INT NOT NULL, student_id INT NOT NULL, title VARCHAR(180), solution TEXT, status VARCHAR(40) DEFAULT 'Submitted', submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(challenge_id) REFERENCES challenges(id), FOREIGN KEY(student_id) REFERENCES users(id));
CREATE TABLE conversations (id INT PRIMARY KEY AUTO_INCREMENT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE conversation_members (conversation_id INT, user_id INT, PRIMARY KEY(conversation_id,user_id), FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE messages (id INT PRIMARY KEY AUTO_INCREMENT, conversation_id INT NOT NULL, sender_id INT NOT NULL, body TEXT NOT NULL, is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE, FOREIGN KEY(sender_id) REFERENCES users(id));
CREATE TABLE notifications (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, title VARCHAR(200) NOT NULL, message TEXT, type VARCHAR(50), is_read TINYINT(1) DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE verifications (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NOT NULL, entity_type VARCHAR(50), status ENUM('Pending','Approved','Rejected') DEFAULT 'Pending', note TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE audit_logs (id INT PRIMARY KEY AUTO_INCREMENT, user_id INT NULL, action VARCHAR(180) NOT NULL, entity_type VARCHAR(80), entity_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX idx_startup_stage ON startups(stage); CREATE INDEX idx_deal_stage ON deals(stage); CREATE INDEX idx_issue_status ON project_issues(status); CREATE INDEX idx_notifications_user ON notifications(user_id,is_read);
